class AdaptiveKVQuantizer:
    """Query-aware mixed-axis KV quantizer with saliency-gated residuals.

    Novelty:
    - uses prefill query energy to derive per-layer importance
    - allocates different bitwidths and residual windows to layers/KV kind
    - preserves a saliency-selected subset of tokens in FP16 instead of a pure tail-only rule
    - mixes key channel-wise and token-wise quantization, choosing the lower-error view online
    """

    def __init__(self):
        self.bits = 4
        self.key_group_size = 32
        self.value_group_size = 32
        self.query_stats = {}
        self.layer_scale = {}
        self.request_workload = ""
        self.long_context = False
        self.num_layers_hint = 36

    def reset_request(self, request_meta: dict, budget_state: dict):
        self.bits = min(4, int(budget_state.get("budget_bits", 4)))
        self.request_workload = str(request_meta.get("workload", ""))
        prompt_chars = int(request_meta.get("prompt_chars", 0))
        self.long_context = self.request_workload.startswith("longbench_") or self.request_workload == "needlebench_niah" or prompt_chars > 6000
        self.query_stats = {}
        self.layer_scale = {}

    def needs_prefill_qkv_observer(self) -> bool:
        return True

    def observe_prefill_qkv(
        self,
        layer_id: int,
        query_states: torch.Tensor | None,
        key_states: torch.Tensor | None,
        value_states: torch.Tensor | None,
        attention_meta: dict,
    ) -> None:
        if query_states is None or query_states.numel() == 0:
            return None
        q = query_states.float()
        token_energy = q.pow(2).mean(dim=-1).mean(dim=1)
        global_energy = float(token_energy.mean().item())
        tail_energy = float(token_energy[:, max(0, token_energy.shape[-1] - min(128, token_energy.shape[-1])) :].mean().item())
        peak_energy = float(token_energy.max().item())
        self.query_stats[layer_id] = {
            "global": global_energy,
            "tail": tail_energy,
            "peak": peak_energy,
        }
        return None

    def query_observation_position(self) -> str:
        return "post_rope"

    def _layer_profile(self, layer_id: int) -> float:
        stats = self.query_stats.get(layer_id)
        if not stats:
            return 1.0
        return float((stats["global"] + stats["tail"] + 0.5 * stats["peak"]) / max(stats["global"], 1e-6))

    def _bits_for(self, layer_id: int, kv_kind: str) -> int:
        p = self._layer_profile(layer_id)
        depth = layer_id / max(self.num_layers_hint - 1, 1)
        if kv_kind == "key":
            if p > 1.35 or depth > 0.78:
                return 4
            if p < 1.08 and depth < 0.25:
                return 2
            return 3
        if p > 1.30 or depth > 0.72:
            return 4
        if p < 1.05 and depth < 0.35:
            return 2
        return 3

    def _residual_keep_length(self, seq_len: int, residual_length: int, residual_policy: str = "tail") -> int:
        residual_length = max(0, min(seq_len, int(residual_length)))
        if residual_length == 0 or residual_policy in {"none", ""}:
            return 0
        if residual_policy == "block_modulo":
            return seq_len % residual_length
        if residual_policy == "tail":
            return residual_length
        raise ValueError(f"Unsupported residual_policy={residual_policy}")

    def _minmax_quantize_last_dim(self, data: torch.Tensor, bits: int, group_size: int) -> torch.Tensor:
        if data.numel() == 0 or bits >= FP_BITS - 0.5:
            return data
        max_int = max(1, int(2**int(bits)) - 1)
        trailing = data.shape[-1]
        group_size = trailing if int(group_size) <= 0 else int(group_size)
        padded = math.ceil(trailing / group_size) * group_size
        work = data if padded == trailing else torch.nn.functional.pad(data, (0, padded - trailing))
        grouped = work.reshape(*work.shape[:-1], padded // group_size, group_size)
        gmin = grouped.amin(dim=-1, keepdim=True)
        gmax = grouped.amax(dim=-1, keepdim=True)
        scale = (gmax - gmin).clamp(min=1e-5) / max_int
        quant = torch.round((grouped - gmin) / scale).clamp(0, max_int)
        dequant = quant.mul(scale).add(gmin)
        return dequant.reshape(*work.shape[:-1], padded)[..., :trailing]

    def _token_importance(self, tensor: torch.Tensor, kv_kind: str) -> torch.Tensor:
        imp = tensor.float().pow(2).mean(dim=(0, 1, 3))
        if kv_kind == "key":
            imp = imp + 0.15 * tensor.float().abs().amax(dim=(0, 1, 3))
        return imp

    def _saliency_residual_quantize(self, layer_tensor: torch.Tensor, *, layer_id: int, kv_kind: str, axis: str) -> tuple[torch.Tensor, float]:
        work = layer_tensor.float().clone()
        batch, heads, seq_len, head_dim = work.shape
        bits = self._bits_for(layer_id, kv_kind)
        base_residual = 96 if self.long_context else 48
        if kv_kind == "value":
            base_residual += 32
        if self._layer_profile(layer_id) > 1.25:
            base_residual += 32
        residual = max(0, min(seq_len, base_residual))
        if seq_len <= residual or bits >= FP_BITS - 0.5:
            return work.to(layer_tensor.dtype), FP_BITS

        importance = self._token_importance(work, kv_kind)
        keep_mask = torch.zeros(seq_len, device=work.device, dtype=torch.bool)
        keep_mask[seq_len - residual :] = True
        extra_keep = max(0, min(seq_len - residual, residual // 2))
        if extra_keep > 0 and seq_len - residual > 0:
            salient_idx = torch.topk(importance[: seq_len - residual], k=extra_keep, largest=True).indices
            keep_mask[salient_idx] = True
        quant_idx = (~keep_mask).nonzero(as_tuple=False).flatten()
        if quant_idx.numel() == 0:
            return work.to(layer_tensor.dtype), FP_BITS

        quant_slice = work[:, :, quant_idx, :]
        if axis == "channel":
            transformed = quant_slice.transpose(2, 3).contiguous()
            dequant = self._minmax_quantize_last_dim(transformed, bits, self.key_group_size).transpose(2, 3)
        else:
            flat = quant_slice.transpose(1, 2).reshape(batch, quant_idx.numel(), heads * head_dim)
            flat = self._minmax_quantize_last_dim(flat, bits, self.value_group_size)
            dequant = flat.reshape(batch, quant_idx.numel(), heads, head_dim).transpose(1, 2)
        work[:, :, quant_idx, :] = dequant
        kept = int(keep_mask.sum().item())
        avg_bits = (quant_idx.numel() * bits + kept * FP_BITS) / max(seq_len, 1)
        return work.to(layer_tensor.dtype), float(avg_bits)

    def quantize_key(self, layer_id: int, key_states: torch.Tensor, cache_meta: dict) -> tuple[torch.Tensor, float]:
        q_channel, b_channel = self._saliency_residual_quantize(key_states, layer_id=layer_id, kv_kind="key", axis="channel")
        q_token, b_token = self._saliency_residual_quantize(key_states, layer_id=layer_id, kv_kind="key", axis="token")
        err_channel = (q_channel.float() - key_states.float()).pow(2).mean()
        err_token = (q_token.float() - key_states.float()).pow(2).mean()
        return (q_channel, b_channel) if err_channel <= err_token else (q_token, b_token)

    def quantize_value(self, layer_id: int, value_states: torch.Tensor, cache_meta: dict) -> tuple[torch.Tensor, float]:
        return self._saliency_residual_quantize(value_states, layer_id=layer_id, kv_kind="value", axis="token")

    def estimate_bits(self, layer_id: int, kv_kind: str, seq_len: int, head_dim: int, cache_meta: dict) -> float:
        bits = self._bits_for(layer_id, kv_kind)
        base_residual = 96 if self.long_context else 48
        if kv_kind == "value":
            base_residual += 32
        if self._layer_profile(layer_id) > 1.25:
            base_residual += 32
        residual = max(0, min(seq_len, base_residual))
        extra_keep = max(0, min(seq_len - residual, residual // 2))
        kept = residual + extra_keep
        quant_tokens = max(0, seq_len - kept)
        return float((quant_tokens * bits + kept * FP_BITS) / max(seq_len, 1))

class AdaptiveKVQuantizer:
    """Prefill-aware adaptive KV quantizer with importance-weighted mixed precision.

    Core contribution:
    1) query-energy-based layer importance from prefill,
    2) smooth mixed-precision bit allocation under a 4-bit cap,
    3) saliency-weighted clipping before quantization,
    4) asymmetric token retention: recent tokens stay FP16 and a small set of
       globally salient historical tokens also stay FP16.
    """

    def __init__(self):
        self.bits = 4
        self.key_group_size = 32
        self.value_group_size = 32
        self.query_stats = {}
        self.request_workload = ""
        self.long_context = False
        self.num_layers_hint = 36

    def reset_request(self, request_meta: dict, budget_state: dict):
        self.bits = min(4, int(budget_state.get("budget_bits", 4)))
        self.request_workload = str(request_meta.get("workload", ""))
        prompt_chars = int(request_meta.get("prompt_chars", 0))
        self.long_context = self.request_workload.startswith("longbench_") or self.request_workload == "needlebench_niah" or prompt_chars > 6000
        self.query_stats = {}

    def needs_prefill_qkv_observer(self) -> bool:
        return True

    def observe_prefill_qkv(
        self,
        layer_id: int,
        query_states: torch.Tensor | None,
        key_states: torch.Tensor | None,
        value_states: torch.Tensor | None,
        attention_meta: dict,
    ) -> None:
        if query_states is None or query_states.numel() == 0:
            return None
        q = query_states.float()
        token_energy = q.pow(2).mean(dim=-1).mean(dim=1)
        prefix = token_energy[:, : max(1, token_energy.shape[-1] // 4)]
        suffix = token_energy[:, max(0, token_energy.shape[-1] - min(128, token_energy.shape[-1])) :]
        self.query_stats[layer_id] = {
            "global": float(token_energy.mean().item()),
            "prefix": float(prefix.mean().item()),
            "suffix": float(suffix.mean().item()),
            "peak": float(token_energy.max().item()),
        }
        return None

    def query_observation_position(self) -> str:
        return "post_rope"

    def _layer_profile(self, layer_id: int) -> float:
        s = self.query_stats.get(layer_id)
        if not s:
            return 1.0
        return float((0.6 * s["global"] + 0.8 * s["suffix"] + 0.3 * s["peak"]) / max(0.7 * s["global"] + 0.3 * s["prefix"], 1e-6))

    def _bits_for(self, layer_id: int, kv_kind: str) -> int:
        p = self._layer_profile(layer_id)
        depth = layer_id / max(self.num_layers_hint - 1, 1)
        if kv_kind == "key":
            if p > 1.50 or depth > 0.84:
                return 4
            if p > 1.18 or depth > 0.58:
                return 3
            return 2
        if p > 1.40 or depth > 0.80:
            return 4
        if p > 1.12 or depth > 0.52:
            return 3
        return 2

    def _minmax_quantize_last_dim(self, data: torch.Tensor, bits: int, group_size: int, clip_factor: float = 1.0) -> torch.Tensor:
        if data.numel() == 0 or bits >= FP_BITS - 0.5:
            return data
        max_int = max(1, int(2**int(bits)) - 1)
        trailing = data.shape[-1]
        group_size = trailing if int(group_size) <= 0 else int(group_size)
        padded = math.ceil(trailing / group_size) * group_size
        work = data if padded == trailing else torch.nn.functional.pad(data, (0, padded - trailing))
        grouped = work.reshape(*work.shape[:-1], padded // group_size, group_size)
        if clip_factor < 0.999:
            center = grouped.mean(dim=-1, keepdim=True)
            radius = (grouped - center).abs().amax(dim=-1, keepdim=True) * clip_factor
            grouped = torch.maximum(torch.minimum(grouped, center + radius), center - radius)
        gmin = grouped.amin(dim=-1, keepdim=True)
        gmax = grouped.amax(dim=-1, keepdim=True)
        scale = (gmax - gmin).clamp(min=1e-5) / max_int
        quant = torch.round((grouped - gmin) / scale).clamp(0, max_int)
        dequant = quant.mul(scale).add(gmin)
        return dequant.reshape(*work.shape[:-1], padded)[..., :trailing]

    def _token_importance(self, tensor: torch.Tensor, kv_kind: str) -> torch.Tensor:
        x = tensor.float()
        energy = x.pow(2).mean(dim=(0, 1, 3))
        peak = x.abs().amax(dim=(0, 1, 3))
        imp = energy + (0.10 if kv_kind == "key" else 0.05) * peak
        trend = torch.linspace(0.85, 1.15, steps=tensor.shape[-2], device=tensor.device, dtype=imp.dtype)
        return imp * trend

    def _residual_plan(self, layer_id: int, kv_kind: str, seq_len: int) -> tuple[int, int]:
        p = self._layer_profile(layer_id)
        recent = 64 if self.long_context else 32
        if kv_kind == "value":
            recent += 32
        if p > 1.20:
            recent += 32
        if p > 1.45:
            recent += 32
        recent = max(0, min(seq_len, recent))
        anchors = 16 if self.long_context else 8
        if kv_kind == "value":
            anchors += 8
        if p > 1.30:
            anchors += 8
        anchors = max(0, min(seq_len - recent, anchors))
        return recent, anchors

    def _quantize_axis(self, work: torch.Tensor, bits: int, axis: str, kv_kind: str) -> torch.Tensor:
        clip_factor = 0.92 if bits <= 2 else (0.96 if kv_kind == "value" else 0.95)
        batch, heads, seq_part, head_dim = work.shape
        if axis == "channel":
            transformed = work.transpose(2, 3).contiguous()
            return self._minmax_quantize_last_dim(transformed, bits, self.key_group_size, clip_factor).transpose(2, 3)
        flat = work.transpose(1, 2).reshape(batch, seq_part, heads * head_dim)
        flat = self._minmax_quantize_last_dim(flat, bits, self.value_group_size, clip_factor)
        return flat.reshape(batch, seq_part, heads, head_dim).transpose(1, 2)

    def _adaptive_quantize(self, layer_tensor: torch.Tensor, *, layer_id: int, kv_kind: str, primary_axis: str) -> tuple[torch.Tensor, float]:
        work = layer_tensor.float().clone()
        seq_len = work.shape[-2]
        bits = self._bits_for(layer_id, kv_kind)
        recent_keep, anchor_keep = self._residual_plan(layer_id, kv_kind, seq_len)
        if seq_len <= recent_keep + anchor_keep or bits >= FP_BITS - 0.5:
            return work.to(layer_tensor.dtype), FP_BITS

        importance = self._token_importance(work, kv_kind)
        keep_mask = torch.zeros(seq_len, device=work.device, dtype=torch.bool)
        if recent_keep > 0:
            keep_mask[seq_len - recent_keep :] = True
        candidate_prefix = max(0, seq_len - recent_keep)
        if anchor_keep > 0 and candidate_prefix > 0:
            anchor_idx = torch.topk(importance[:candidate_prefix], k=anchor_keep, largest=True).indices
            keep_mask[anchor_idx] = True
        quant_idx = (~keep_mask).nonzero(as_tuple=False).flatten()
        if quant_idx.numel() == 0:
            return work.to(layer_tensor.dtype), FP_BITS

        quant_slice = work[:, :, quant_idx, :]
        q_primary = self._quantize_axis(quant_slice, bits, primary_axis, kv_kind)
        err_primary = (q_primary - quant_slice).pow(2).mean()
        if kv_kind == "key":
            alt_axis = "token" if primary_axis == "channel" else "channel"
            q_alt = self._quantize_axis(quant_slice, bits, alt_axis, kv_kind)
            err_alt = (q_alt - quant_slice).pow(2).mean()
            quantized = q_primary if err_primary <= err_alt else q_alt
        else:
            quantized = q_primary
        work[:, :, quant_idx, :] = quantized
        kept = int(keep_mask.sum().item())
        avg_bits = (quant_idx.numel() * bits + kept * FP_BITS) / max(seq_len, 1)
        return work.to(layer_tensor.dtype), float(avg_bits)

    def quantize_key(self, layer_id: int, key_states: torch.Tensor, cache_meta: dict) -> tuple[torch.Tensor, float]:
        return self._adaptive_quantize(key_states, layer_id=layer_id, kv_kind="key", primary_axis="channel")

    def quantize_value(self, layer_id: int, value_states: torch.Tensor, cache_meta: dict) -> tuple[torch.Tensor, float]:
        return self._adaptive_quantize(value_states, layer_id=layer_id, kv_kind="value", primary_axis="token")

    def estimate_bits(self, layer_id: int, kv_kind: str, seq_len: int, head_dim: int, cache_meta: dict) -> float:
        bits = self._bits_for(layer_id, kv_kind)
        recent_keep, anchor_keep = self._residual_plan(layer_id, kv_kind, seq_len)
        kept = recent_keep + anchor_keep
        quant_tokens = max(0, seq_len - kept)
        return float((quant_tokens * bits + kept * FP_BITS) / max(seq_len, 1))
